import sys
from collections import defaultdict, deque

input = sys.stdin.readline

def solve(n, m, edges):
    adj_list = defaultdict(list)
    for a, b in edges:
        adj_list[a].append(b)
        adj_list[b].append(a)

    degree = [0] * (n + 1)
    for i in range(1, n + 1):
        degree[i] = len(adj_list[i])

    for start in range(1, n + 1):
        queue = deque([start])
        visited = [False] * (n + 1)
        visited[start] = True
        stolen = []

        while queue:
            node = queue.popleft()
            if degree[node] % 3 == 0:
                stolen.append(node)
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        if len(stolen) > 0 and len(stolen) < n:
            print("Yes")
            print(len(stolen))
            print(" ".join(map(str, stolen)))
            return

    print("No")

def main():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        edges = [tuple(map(int, input().split())) for _ in range(m)]
        solve(n, m, edges)
        if _ < t - 1:
            input()  # Skip the empty line after each test case except the last one

if __name__ == "__main__":
    main()
